 1→import styled from "@emotion/styled";
 2→import {
 3→  Select,
 4→  Option,
 5→  SelectProps,
 6→  Size as SelectSize,
 7→} from "@leafygreen-ui/select";
 8→import { PAGE_SIZES } from "../../constants/pagination";
 9→
10→interface Props {
11→  value: number;
12→  disabled?: boolean;
13→  onChange: (i: number) => void;
14→}
15→
16→/**
17→ * `data-*` props are not currently supported by `@leafygreen-ui/select`
18→ *  https://jira.mongodb.org/browse/EVG-16932
19→ * @param props - React props passed to the component
20→ * @param props.value - The current page size
21→ * @param props.onChange - Callback to be called when the page size is changed
22→ * @param props.disabled - If the page size selector should be disabled
23→ * @returns The PageSizeSelector component
24→ */
25→const PageSizeSelector: React.FC<Props> = ({
26→  disabled = false,
27→  onChange,
28→  value,
29→  ...rest
30→}) => (
31→  <StyledSelect
32→    allowDeselect={false}
33→    aria-labelledby="page-size-select"
34→    disabled={disabled}
35→    onChange={(pageSize: string) => onChange(parseInt(pageSize, 10))}
36→    size={SelectSize.Small}
37→    value={value.toString()}
38→    {...rest}
39→  >
40→    {PAGE_SIZES.map((limit) => (
41→      <Option key={limit} value={limit.toString()}>{`${limit} / page`}</Option>
42→    ))}
43→  </StyledSelect>
44→);
45→
46→const StyledSelect = styled(
47→  Select as unknown as React.ComponentType<Partial<SelectProps>>,
48→)`
49→  width: 120px;
50→`;
51→
52→export default PageSizeSelector;
