  1→import { ForwardedRef, forwardRef, Fragment } from "react";
  2→import { SerializedStyles } from "@emotion/react";
  3→import styled from "@emotion/styled";
  4→import { css } from "@leafygreen-ui/emotion";
  5→import { Pagination } from "@leafygreen-ui/pagination";
  6→import { palette } from "@leafygreen-ui/palette";
  7→import {
  8→  Cell,
  9→  ExpandedContent,
 10→  flexRender,
 11→  HeaderCell,
 12→  HeaderRow,
 13→  Row,
 14→  type RowData,
 15→  Table,
 16→  TableBody,
 17→  type TableProps,
 18→  TableHead,
 19→  VirtualItem,
 20→  LeafyGreenTableRow,
 21→  LeafyGreenTable,
 22→  LeafyGreenVirtualTable,
 23→  Header,
 24→  LGTableDataType,
 25→  type LGRowData,
 26→  ExpandedContentProps,
 27→} from "@leafygreen-ui/table";
 28→import { tableColumnOffset, size } from "../../constants/tokens";
 29→import { conditionalToArray } from "../../utils/array";
 30→import { TreeDataEntry } from "../TreeSelect";
 31→import TableLoader from "./TableLoader";
 32→import TableFilterPopover from "./TablePopover/TableFilterPopover";
 33→import TableSearchPopover from "./TablePopover/TableSearchPopover";
 34→
 35→const { gray } = palette;
 36→
 37→// Define typing of columns' meta field
 38→// https://tanstack.com/table/v8/docs/api/core/column-def#meta
 39→declare module "@tanstack/table-core" {
 40→  // eslint-disable-next-line @typescript-eslint/no-unused-vars
 41→  interface ColumnMeta<TData extends RowData, TValue> {
 42→    search?: {
 43→      "data-cy"?: string;
 44→      placeholder?: string;
 45→    };
 46→    treeSelect?: {
 47→      "data-cy"?: string;
 48→      // Configures whether or not the tree select should be filtered to only represent values found in the table.
 49→      // Note that this may not be very performant for large tables.
 50→      filterOptions?: boolean;
 51→      options: TreeDataEntry[];
 52→    };
 53→    // Overcome react-table's column width limitations
 54→    // https://github.com/TanStack/table/discussions/4179#discussioncomment-3334470
 55→    width?: string;
 56→  }
 57→}
 58→
 59→const { blue } = palette;
 60→
 61→interface SpruceTableProps<T extends LGRowData> {
 62→  "data-cy-row"?: string;
 63→  "data-cy-table"?: string;
 64→  emptyComponent?: React.ReactNode;
 65→  loading?: boolean;
 66→  /** estimated number of rows the table will have */
 67→  loadingRows?: number;
 68→  /** number of total items the table will have */
 69→  numTotalItems?: number;
 70→  /** rows that will have a blue tint to represent that they are selected */
 71→  selectedRowIndexes?: number[];
 72→  /** rows that will have a disabled style */
 73→  disabledRowIndexes?: number[];
 74→  /** whether the table is paginated */
 75→  usePagination?: boolean;
 76→  /** Object returned from the useLeafyGreenTable or useLeafyGreenVirtualTable hook */
 77→  table: LeafyGreenVirtualTable<T> | LeafyGreenTable<T>;
 78→  /** CSS to apply to the table rows */
 79→  rowCss?: SerializedStyles;
 80→}
 81→
 82→type BaseTableProps<T extends LGRowData = LGRowData> = SpruceTableProps<T> &
 83→  Omit<TableProps<T>, "table">;
 84→
 85→// eslint-disable-next-line @typescript-eslint/no-explicit-any
 86→export const BaseTable = forwardRef<HTMLDivElement, BaseTableProps<any>>(
 87→  <T extends LGRowData>(
 88→    {
 89→      "data-cy-row": dataCyRow,
 90→      "data-cy-table": dataCyTable,
 91→      disabledRowIndexes = [],
 92→      emptyComponent,
 93→      loading,
 94→      loadingRows = 5,
 95→      numTotalItems,
 96→      rowCss,
 97→      selectedRowIndexes = [],
 98→      table,
 99→      usePagination = false,
100→      verticalAlignment = "middle",
101→      ...args
102→    }: BaseTableProps<T>,
103→    ref: ForwardedRef<HTMLDivElement>,
104→  ) => {
105→    const { rows } = table.getRowModel();
106→
107→    const virtualRows = table.virtual?.getVirtualItems();
108→    const hasVirtualRows = virtualRows && virtualRows.length > 0;
109→
110→    return (
111→      <>
112→        <Table
113→          ref={ref}
114→          data-cy={dataCyTable}
115→          table={table}
116→          verticalAlignment={verticalAlignment}
117→          {...args}
118→        >
119→          <TableHead isSticky={hasVirtualRows}>
120→            {table.getHeaderGroups().map((headerGroup) => (
121→              <HeaderRow key={headerGroup.id}>
122→                {headerGroup.headers.map((header) => (
123→                  <TableHeaderCell
124→                    key={header.id}
125→                    header={header}
126→                    table={table}
127→                    usePagination={usePagination}
128→                  />
129→                ))}
130→              </HeaderRow>
131→            ))}
132→          </TableHead>
133→          <TableBody>
134→            {loading && (
135→              <TableLoader
136→                numColumns={table.getAllColumns().length}
137→                numRows={loadingRows}
138→              />
139→            )}
140→
141→            {hasVirtualRows
142→              ? virtualRows.map((vr) => {
143→                  const { row } = vr;
144→                  return (
145→                    <RenderableRow
146→                      key={row.id}
147→                      dataCyRow={dataCyRow}
148→                      disabled={disabledRowIndexes?.includes(row.index)}
149→                      isSelected={selectedRowIndexes.includes(row.index)}
150→                      row={row}
151→                      rowCss={rowCss}
152→                      virtualRow={vr}
153→                    />
154→                  );
155→                })
156→              : rows.map((row) => (
157→                  <RenderableRow
158→                    key={row.id}
159→                    dataCyRow={dataCyRow}
160→                    disabled={disabledRowIndexes?.includes(row.index)}
161→                    isSelected={selectedRowIndexes.includes(row.index)}
162→                    row={row}
163→                    rowCss={rowCss}
164→                  />
165→                ))}
166→          </TableBody>
167→        </Table>
168→        {!loading &&
169→          rows.length === 0 &&
170→          (emptyComponent || (
171→            <DefaultEmptyMessage>No data to display</DefaultEmptyMessage>
172→          ))}
173→        {usePagination && table && (
174→          <StyledPagination
175→            currentPage={table.getState().pagination.pageIndex + 1}
176→            itemsPerPage={table.getState().pagination.pageSize}
177→            numTotalItems={numTotalItems}
178→            onBackArrowClick={() => table.previousPage()}
179→            onCurrentPageOptionChange={(value: string) => {
180→              table.setPageIndex(Number(value) - 1);
181→            }}
182→            onForwardArrowClick={() => table.nextPage()}
183→            onItemsPerPageOptionChange={(value: string) => {
184→              table.setPageSize(Number(value));
185→            }}
186→          />
187→        )}
188→      </>
189→    );
190→  },
191→);
