 3→/**
 4→ * `useOnClickOutside` is a hook that executes a callback when a click is detected outside of the provided refs.
 5→ * @param refs - array of refs to check if the click is outside of
 6→ * @param cb - callback to execute when the click is outside of the refs
 7→ */
 8→export const useOnClickOutside = (
 9→  refs: Array<RefObject<HTMLElement>>,
10→  cb: () => void,
11→): void => {
12→  useEffect(() => {
13→    /**
14→     * `handleClickOutside` executes the callback if a mouse click is detected outside of the target elements.
15→     * @param event - the event that is being listened to
16→     */
17→    function handleClickOutside(event: MouseEvent): void {
18→      const isNotFocused = refs.every(
19→        (ref) => ref.current && !ref.current.contains(event.target as Node),
20→      );
21→      if (isNotFocused) {
22→        cb();
23→      }
24→    }
25→    document.addEventListener("mousedown", handleClickOutside);
26→    return (): void => {
27→      document.removeEventListener("mousedown", handleClickOutside);
28→    };
29→  }, [cb, refs]);
30→};
