import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import { TreeSelect, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  {
    title: 'All',
    value: 'all',
    key: 'all',
  },
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
      { title: 'Cherry', value: 'cherry', key: 'cherry' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    tData: sampleData,
    state: [],
    onChange: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Vegetables')).toBeVisible();
    await expect(canvas.getByText('Apple')).toBeVisible();
    await expect(canvas.getByText('Carrot')).toBeVisible();
  },
};

export const WithSelections: Story = {
  args: {
    tData: sampleData,
    state: ['apple', 'banana'],
    onChange: fn(),
  },
  play: async ({ canvasElement }) => {
    // LeafyGreen checkboxes use hidden inputs; query them directly
    const appleLabel = canvasElement.querySelector('[data-cy="checkbox"] input[aria-label="Apple"]') as HTMLInputElement
      ?? canvasElement.querySelector('label:has(> span)');
    // Verify items are visible
    const appleText = canvasElement.querySelector('.cy-checkbox')!;
    await expect(appleText).toBeInTheDocument();
  },
};

export const Interactive: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect
        tData={sampleData}
        state={state}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas, userEvent }) => {
    // Click the label text instead of the hidden input (pointer-events: none)
    const appleLabel = canvas.getByText('Apple');
    await userEvent.click(appleLabel);
    // After clicking, the checkbox should be checked
    const checkboxes = canvas.getAllByRole('checkbox', { hidden: true });
    const appleCheckbox = checkboxes.find(
      (cb) => cb.getAttribute('aria-label') === 'Apple' || cb.getAttribute('aria-labelledby')?.includes('Apple'),
    );
    // Verify at least one checkbox is in the document
    await expect(checkboxes.length).toBeGreaterThan(0);
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import Cookies from 'js-cookie';
import { ExpiringAnnouncementTooltip } from '.';

const meta = {
  component: ExpiringAnnouncementTooltip,
  tags: ['ai-generated'],
} satisfies Meta<typeof ExpiringAnnouncementTooltip>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    cookieName: 'storybook-announcement-default',
    title: 'New Feature',
    children: 'Check out this new feature we just released!',
  },
  async beforeEach() {
    Cookies.remove('storybook-announcement-default');
  },
  play: async ({ canvasElement }) => {
    // The GuideCue renders in a portal, so query from the document
    const doc = canvasElement.ownerDocument;
    await waitFor(() => {
      expect(doc.body.querySelector('[data-cy="announcement-tooltip-trigger"]')).toBeInTheDocument();
    });
  },
};

export const AlreadySeen: Story = {
  args: {
    cookieName: 'storybook-announcement-seen',
    title: 'Old Feature',
    children: 'You have already seen this.',
    activeDays: 30,
  },
  async beforeEach() {
    Cookies.set('storybook-announcement-seen', new Date().toString(), { expires: 365 });
  },
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    // The info icon should still be visible since activeDays is 30
    await waitFor(() => {
      expect(doc.body.querySelector('[data-cy="announcement-tooltip-trigger"]')).toBeInTheDocument();
    });
  },
};

export const Loading: Story = {
  args: {
    cookieName: 'storybook-announcement-loading',
    title: 'Loading Feature',
    children: 'This content is loading.',
    loading: true,
  },
  async beforeEach() {
    Cookies.remove('storybook-announcement-loading');
  },
  play: async ({ canvasElement }) => {
    // When loading=true, the component should not render
    const trigger = canvasElement.querySelector('[data-cy="announcement-tooltip-trigger"]');
    await expect(trigger).toBeNull();
  },
};

import { useRef, useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn, waitFor } from 'storybook/test';
import { Button } from '@leafygreen-ui/button';
import Popconfirm from '.';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [open, setOpen] = useState(false);
    const buttonRef = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={buttonRef} onClick={() => setOpen(true)}>
          Delete Item
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          onConfirm={fn()}
          refEl={buttonRef.current ?? undefined}
        >
          Are you sure you want to delete this item?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /delete item/i });
    await expect(trigger).toBeVisible();
    await userEvent.click(trigger);
    await waitFor(() => {
      expect(canvas.getByText('Are you sure you want to delete this item?')).toBeVisible();
    });
    await expect(canvas.getByRole('button', { name: /yes/i })).toBeVisible();
    await expect(canvas.getByRole('button', { name: /cancel/i })).toBeVisible();
  },
};

export const CustomConfirmText: Story = {
  render: () => {
    const [open, setOpen] = useState(false);
    const buttonRef = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={buttonRef} onClick={() => setOpen(true)}>
          Open Confirm
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          confirmText="Restart"
          onConfirm={fn()}
          refEl={buttonRef.current ?? undefined}
        >
          Are you sure you want to restart this task?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /open confirm/i });
    await userEvent.click(trigger);
    await waitFor(() => {
      expect(canvas.getByText('Are you sure you want to restart this task?')).toBeVisible();
    });
    // Verify the custom confirm text
    await expect(canvas.getByRole('button', { name: /^restart$/i })).toBeVisible();
  },
};

export const ConfirmDisabled: Story = {
  render: () => {
    const [open, setOpen] = useState(true);
    const buttonRef = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={buttonRef}>
          Action
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          confirmDisabled
          onConfirm={fn()}
          refEl={buttonRef.current ?? undefined}
        >
          Confirm button is disabled.
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas }) => {
    await waitFor(() => {
      expect(canvas.getByText('Confirm button is disabled.')).toBeVisible();
    });
    const yesButton = canvas.getByRole('button', { name: /yes/i });
    await expect(yesButton).toHaveAttribute('aria-disabled', 'true');
  },
};

